CREATE TABLE Department (
    Department_Address VARCHAR(255),
    Department_ID INTEGER PRIMARY KEY,
    Department_Name VARCHAR(255),
    Department_Phone INTEGER,
    Staff VARCHAR(255)
);

CREATE TABLE Patient (
    Age INTEGER,
    Contact_Information INTEGER,
    Diagnosis_Description VARCHAR(255),
    Gender VARCHAR(255),
    Name VARCHAR(255),
    Patient_ID INTEGER PRIMARY KEY,
    Visit_Date DATETIME
);

CREATE TABLE Ward (
    Number_of_Beds INTEGER,
    Ward_Level VARCHAR(255),
    Ward_Number INTEGER PRIMARY KEY
);

CREATE TABLE Registration_Category (
    Category_ID INTEGER PRIMARY KEY,
    Category_Name VARCHAR(255)
);

CREATE TABLE Medicine (
    Barcode VARCHAR(255),
    Medicine_ID INTEGER PRIMARY KEY,
    Name VARCHAR(255),
    Price FLOAT,
    Quantity INTEGER
);

CREATE TABLE Prescription (
    Medicine_Information VARCHAR(255),
    Prescription_ID INTEGER PRIMARY KEY
);

CREATE TABLE Doctor (
    Date_of_Birth DATETIME,
    Doctor_ID INTEGER PRIMARY KEY,
    Gender VARCHAR(255),
    Name VARCHAR(255),
    Title VARCHAR(255),
    Work_Certificate VARCHAR(255),
    Years_of_Employment INTEGER
);

CREATE TABLE Treatment (
    Case_Number INTEGER PRIMARY KEY,
    Patient_ID INTEGER NOT NULL,
    Treatment_Content VARCHAR(255),
    FOREIGN KEY (Patient_ID) REFERENCES Patient(Patient_ID)
);

CREATE TABLE Prescription_Medicine (
    Medicine_ID INTEGER NOT NULL,
    Prescription_ID INTEGER NOT NULL,
    Quantity INTEGER,
    PRIMARY KEY (Prescription_ID, Medicine_ID),
    FOREIGN KEY (Medicine_ID) REFERENCES Medicine(Medicine_ID),
    FOREIGN KEY (Prescription_ID) REFERENCES Prescription(Prescription_ID)
);
